UPDATE payment_requests
SET status = 'COMPLETED',
    transaction_id = #{transactionId}
WHERE payment_id = #{paymentId}
  AND status = 'PROCESSING'

UPDATE payment_requests
SET status = 'FAILED',
    failure_code = #{failureCode}
WHERE payment_id = #{paymentId}
  AND status = 'PROCESSING'
